/* Local-only XLSX/CSV decoding. Does not evaluate workbook formulas. */
(()=>{'use strict';
function csv(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0],sep=(first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?';':first.includes('\t')?'\t':',';const rows=[];let row=[],v='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){v+='"';i++}else q=!q}else if(c===sep&&!q){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);rows.push(row);row=[];v=''}else v+=c}if(q)throw Error('CSV มีเครื่องหมายคำพูดไม่ครบ');if(v||row.length){row.push(v);rows.push(row)}return rows}
async function unzip(buffer){const d=new DataView(buffer),bytes=new Uint8Array(buffer),files=new Map();let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(d.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('ไฟล์ Excel ไม่ใช่ XLSX ที่รองรับ');let pos=d.getUint32(end+16,true),count=d.getUint16(end+10,true),total=0;if(count>3000)throw Error('ไฟล์มีจำนวนส่วนข้อมูลมากเกินไป');for(let i=0;i<count;i++){if(d.getUint32(pos,true)!==0x02014b50)throw Error('โครงสร้าง XLSX ไม่ครบ');const method=d.getUint16(pos+10,true),size=d.getUint32(pos+20,true),raw=d.getUint32(pos+24,true),nl=d.getUint16(pos+28,true),ex=d.getUint16(pos+30,true),co=d.getUint16(pos+32,true),off=d.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nl));total+=raw;if(total>80*1024*1024)throw Error('ข้อมูล Excel หลังขยายมีขนาดเกิน 80 MB');files.set(name,{method,size,raw,off});pos+=46+nl+ex+co}return async name=>{const f=files.get(name);if(!f)return null;const start=f.off+30+d.getUint16(f.off+26,true)+d.getUint16(f.off+28,true);let b=bytes.slice(start,start+f.size);if(f.method===8){const stream=new Blob([b]).stream().pipeThrough(new DecompressionStream('deflate-raw'));b=new Uint8Array(await new Response(stream).arrayBuffer())}else if(f.method!==0)throw Error('รูปแบบบีบอัด XLSX ไม่รองรับ');if(b.length!==f.raw)throw Error('ข้อมูล XLSX ไม่ครบ');return new TextDecoder().decode(b)}}
const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('ข้อมูล XML ใน Excel ไม่สมบูรณ์');return d};const elements=(node,name)=>Array.from(node.getElementsByTagNameNS('*',name));
async function xlsx(buffer){const read=await unzip(buffer),strings=await read('xl/sharedStrings.xml'),ss=strings?elements(xml(strings),'si').map(x=>elements(x,'t').map(t=>t.textContent).join('')):[],wb=xml(await read('xl/workbook.xml')),sheet=elements(wb,'sheet')[0];if(!sheet)throw Error('Excel ไม่มีชีตข้อมูล');const rel=xml(await read('xl/_rels/workbook.xml.rels')),id=sheet.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'),target=elements(rel,'Relationship').find(r=>r.getAttribute('Id')===id)?.getAttribute('Target');if(!target||target.includes('..'))throw Error('ไม่พบชีต Excel');const path=target.startsWith('/')?target.slice(1):'xl/'+target;const data=await read(path);if(!data)throw Error('ไม่พบข้อมูลชีต');const rows=elements(xml(data),'row').map(r=>{const a=[];for(const c of elements(r,'c')){const letters=(c.getAttribute('r')||'').replace(/[0-9]/g,'');let col=0;for(const l of letters)col=col*26+l.charCodeAt(0)-64;let v=elements(c,'v')[0]?.textContent??'';if(c.getAttribute('t')==='s')v=ss[Number(v)]??'';else if(c.getAttribute('t')==='inlineStr')v=elements(c,'t').map(t=>t.textContent).join('');a[col-1]=v}a.sourceRow=Number(r.getAttribute('r'));return a});return {rows,sheet:sheet.getAttribute('name')}}
const norm=x=>String(x??'').trim().toLowerCase().replace(/[\s_()°.]/g,'');
function points(rows){let lat=-1,lon=-1,rssi=-1,name=-1,base=-1,headerEnd=0;for(let i=0;i<Math.min(10,rows.length);i++){rows[i].forEach((v,j)=>{const s=norm(v);if(['lat','latitude','ละติจูด'].includes(s)){lat=j;headerEnd=Math.max(headerEnd,i)}if(['long','lon','lng','longitude','ลองจิจูด'].includes(s)){lon=j;headerEnd=Math.max(headerEnd,i)}if(s.startsWith('rssi')){rssi=j;headerEnd=Math.max(headerEnd,i)}if(['สถานี','ชื่อสถานี','name','station','ชื่อลูกข่าย'].includes(s))name=j;if(s.includes('แม่ข่าย')||['base','basestation'].includes(s))base=j})}if([lat,lon,rssi].includes(-1))throw Error('ไม่พบหัวคอลัมน์ LAT, LONG และ RSSI ใน 10 แถวแรก');const good=[],skipped=[];for(let i=headerEnd+1;i<rows.length;i++){const r=rows[i],a=[r[lat],r[lon],r[rssi]];if(a.every(v=>v===undefined||String(v).trim()===''))continue;const vals=a.map(v=>v===undefined||String(v).trim()===''?NaN:Number(String(v).trim()));if(!vals.every(Number.isFinite)||Math.abs(vals[0])>85||Math.abs(vals[1])>180||vals[2]>0||vals[2]<-160){skipped.push(r.sourceRow||i+1);continue}good.push({lat:vals[0],lon:vals[1],rssi:vals[2],name:String(r[name]||'จุด '+(r.sourceRow||i+1)),base:String(r[base]||''),row:r.sourceRow||i+1});if(good.length>20000)throw Error('รองรับไม่เกิน 20,000 จุดต่อไฟล์')}if(!good.length)throw Error('ไม่พบจุดที่มีพิกัดและ RSSI ถูกต้อง');return {points:good,skipped}}
globalThis.RFFieldReader={async read(file){if(file.size>20*1024*1024)throw Error('ไฟล์ต้องมีขนาดไม่เกิน 20 MB');if(/\.xls$/i.test(file.name))throw Error('กรุณาบันทึกไฟล์ .xls เป็น .xlsx หรือ CSV ก่อนนำเข้า');let data;if(/\.xlsx$/i.test(file.name))data=await xlsx(await file.arrayBuffer());else if(/\.csv$/i.test(file.name))data={rows:csv(await file.text()),sheet:'CSV'};else throw Error('รองรับ XLSX หรือ CSV');return {...points(data.rows),sheet:data.sheet}},csv,points};
})();
